import{i as e,r as t,s as n,t as r}from"./app-DuH0mZgh.js";var i=JSON.parse(`{"path":"/23-Performance_Testing_Plan.html","title":"性能与容量测试计划","lang":"en-US","frontmatter":{},"filePathRelative":"23-Performance_Testing_Plan.md","git":{"createdTime":1765122408000,"updatedTime":1765122408000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`23-Performance_Testing_Plan.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="性能与容量测试计划" tabindex="-1"><a class="header-anchor" href="#性能与容量测试计划"><span>性能与容量测试计划</span></a></h1><blockquote><p>目的：明确 Apollo MMO 在各阶段的性能、容量、可靠性验证策略，为 NetCore、AOI、DataProxy 等模块提供可重复的测试方法，确保满足 P99 &lt; 60 ms、5000+ CCU 的指标。</p></blockquote><h2 id="_1-目标" tabindex="-1"><a class="header-anchor" href="#_1-目标"><span>1. 目标</span></a></h2><ol><li><strong>早期验证</strong>：在开发阶段持续对关键模块进行性能回归，避免后期出现瓶颈。</li><li><strong>系统级压测</strong>：在接近真实环境（Staging）下模拟 5k-10k 并发玩家，测量端到端延迟、吞吐、稳定性。</li><li><strong>容量规划</strong>：通过测试结果推导所需服务器资源、扩容策略。</li><li><strong>故障演练</strong>：结合压力测试，验证容灾、自愈机制。</li></ol><h2 id="_2-测试环境与工具" tabindex="-1"><a class="header-anchor" href="#_2-测试环境与工具"><span>2. 测试环境与工具</span></a></h2><h3 id="_2-1-环境" tabindex="-1"><a class="header-anchor" href="#_2-1-环境"><span>2.1 环境</span></a></h3><ul><li><strong>Test</strong>：模块级压力测试，配置较小（单机/小集群）。</li><li><strong>Staging</strong>：与生产结构一致（Gate/Zone/AOI/DataProxy/DB/Redis/Kafka），可自动扩缩。</li><li><strong>网络条件</strong>：在压测工具中注入不同 RTT/丢包策略，模拟弱网。</li></ul><h3 id="_2-2-工具" tabindex="-1"><a class="header-anchor" href="#_2-2-工具"><span>2.2 工具</span></a></h3><ul><li>自研 C++/Go 压测客户端（基于 NetCore 协议）。</li><li>Unity SDK 压测脚本，模拟真实客户端行为。</li><li>Locust/JMeter 作为 HTTP API 压测工具。</li><li>Chaos/故障注入工具（模拟网络抖动、服务故障）。</li><li>指标收集：Prometheus + Grafana + Jaeger。</li></ul><h2 id="_3-模块级性能测试" tabindex="-1"><a class="header-anchor" href="#_3-模块级性能测试"><span>3. 模块级性能测试</span></a></h2><table><thead><tr><th>模块</th><th>指标</th><th>测试内容</th></tr></thead><tbody><tr><td>NetCore</td><td>吞吐、延迟、CPU、内存</td><td>- io_uring/IOCP 单机连接数<br>- 消息打包/解包耗时<br>- KCP/TCP 比较</td></tr><tr><td>AOI Service</td><td>Enter/Leave 处理延迟</td><td>- AOI shard 承载玩家数<br>- 空间索引性能</td></tr><tr><td>DataProxy</td><td>QPS、延迟、队列长度</td><td>- Load/Save 批处理<br>- Redis 缓存命中率<br>- 写队列/落库速率</td></tr><tr><td>Battle Service</td><td>Tick 时间</td><td>- 大规模技能释放<br>- 状态同步</td></tr><tr><td>Transport/NNG</td><td>延迟、队列</td><td>- IPC/TCP 切换性能<br>- 背压控制效果</td></tr></tbody></table><h2 id="_4-场景-玩法压测" tabindex="-1"><a class="header-anchor" href="#_4-场景-玩法压测"><span>4. 场景/玩法压测</span></a></h2><h3 id="_4-1-基础场景" tabindex="-1"><a class="header-anchor" href="#_4-1-基础场景"><span>4.1 基础场景</span></a></h3><ul><li>主城/野外：5000+ 玩家移动、聊天、交易。</li><li>副本：每个 Zone 50-100 玩家，模拟副本入口/结算。</li><li>AOI 边缘案例：大量单位聚集、频繁 Enter/Leave。</li></ul><h3 id="_4-2-战斗场景" tabindex="-1"><a class="header-anchor" href="#_4-2-战斗场景"><span>4.2 战斗场景</span></a></h3><ul><li>小规模战斗：100v100，技能与 Buff 频繁触发。</li><li>大型战场（Battle Service）：500+ 玩家集中释放技能。</li><li>技能/状态同步延迟、命中判定准确率。</li></ul><h3 id="_4-3-社交与经济" tabindex="-1"><a class="header-anchor" href="#_4-3-社交与经济"><span>4.3 社交与经济</span></a></h3><ul><li>公会战、聊天、邮件、交易、市场波动，确保 DataProxy/TLog 承载。</li></ul><h2 id="_5-压测指标与阈值" tabindex="-1"><a class="header-anchor" href="#_5-压测指标与阈值"><span>5. 压测指标与阈值</span></a></h2><table><thead><tr><th>指标</th><th>目标</th></tr></thead><tbody><tr><td>客户端 RTT</td><td>平均 &lt; 80 ms，P99 &lt; 150 ms</td></tr><tr><td>服务器处理延迟（Gate→Zone）</td><td>P99 &lt; 60 ms</td></tr><tr><td>AOI 事件延迟</td><td>平均 &lt; 30 ms</td></tr><tr><td>DataProxy 写延迟</td><td>平均 &lt; 100 ms</td></tr><tr><td>NetCore CPU 占用</td><td>单线程 &lt; 60%</td></tr><tr><td>内存</td><td>无泄露，长期压测稳定</td></tr><tr><td>TLog Backlog</td><td>&lt; 1 分钟</td></tr></tbody></table><h2 id="_6-故障与可靠性测试" tabindex="-1"><a class="header-anchor" href="#_6-故障与可靠性测试"><span>6. 故障与可靠性测试</span></a></h2><ul><li><strong>断线/重连</strong>：模拟网络波动，检查 SDK/NetCore 自动重连。</li><li><strong>服务宕机</strong>：在压测中随机停止 Gate/Zone/AOI，验证 Orchestrator/Transport 回退机制。</li><li><strong>数据层故障</strong>: Redis/MySQL/Kafka 故障注入，观察 DataProxy 重试、限流、回滚。</li><li><strong>DDoS 场景</strong>：模拟大量无效连接，测试防刷与限流策略。</li></ul><h2 id="_7-流程与自动化" tabindex="-1"><a class="header-anchor" href="#_7-流程与自动化"><span>7. 流程与自动化</span></a></h2><ul><li>每次 CI 构建后触发模块级基准测试（可选）。</li><li>每周运行一次系统级压测（Staging），输出报告。</li><li>发布前进行全链路压测 + 故障演练，作为上线准入条件。</li><li>录制压测脚本/场景，版本化管理，确保可复现。</li></ul><h2 id="_8-报告与决策" tabindex="-1"><a class="header-anchor" href="#_8-报告与决策"><span>8. 报告与决策</span></a></h2><ul><li>指标与结论写入性能报告（CPU/内存/吞吐曲线、瓶颈分析、优化建议）。</li><li>使用报告指导容量规划（每种服务器规格可支撑多少玩家）。</li><li>对于不达标项，创建优化任务并纳入迭代。</li></ul><h2 id="_9-roadmap" tabindex="-1"><a class="header-anchor" href="#_9-roadmap"><span>9. Roadmap</span></a></h2><ol><li>完成基础压测工具（客户端模拟器、脚本）。</li><li>建立自动化压测环境（Staging 集群 + Pipelines）。</li><li>逐步覆盖各模块基准测试（NetCore/AOI/DataProxy/Battle）。</li><li>上线系统级压测 + 故障注入。</li><li>集成压测结果到部署流程（发布前必须通过）。</li></ol><hr><p>该计划确保性能目标可衡量、压测任务有章可循，为上线做好准备。***</p>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};